número de velocidades y distinto accionamiento; no se promedian ni se copian.","shifter_compatibility_claims":"Declaraciones documentadas de la fuente. Cuando el documento no enumera modelos se declara la interfaz o el estándar; no se inventa un nombre para llenar la celda, y un año ausente en la fuente se deja ausente. Una declaración no convierte a esta pieza en compatible con todo lo que comparta marca o número de velocidades.","shifter_unit_compatibility_claims":"Cada declaración pertenece al mando indicado. No se transmite al otro mando del par."},"evidence_requirements":{"shifter_position":"package_or_label","shifter_indexed_positions":"oem_or_package","handlebar_clamp_mm":"oem_or_package","drivetrain_speeds":"name_reading_hint_only","front_chainring_count":"name_reading_hint_only","shift_actuation_family":"oem_spec","derailleur_models_compatible":"oem_spec","kit_members":"package_or_label","drivetrain_primary_ecosystem":"name_reading_hint_only","drivetrain_declared_compatible_ecosystems":"oem_spec","drivetrain_platform":"oem_spec","spec_evidence_source":"oem_or_package","shifter_actuation_mode":"oem_or_package","shifter_control_style":"oem_or_package","shifter_unit_count":"oem_or_package","shifter_units":"oem_or_package","shifter_compatibility_claims":"oem_or_package","shifter_unit_compatibility_claims":"oem_or_package"},"row_conditions":{"version":1,"fields":{"shifter_units":{"allowed_when":{"indexed_positions":{"kind":"when","rows":[[{"field":"actuation_mode","operator":"in","value_type":"token","value":["Indexado","Conmutable entre indexado y fricción"]}]]}},"required_when":{"indexed_positions":{"kind":"when","rows":[[{"field":"actuation_mode","operator":"in","value_type":"token","value":["Indexado","Conmutable entre indexado y fricción"]}]]}}},"shifter_compatibility_claims":{"allowed_when":{"brand":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"model":{"kind":"when","rows":[[{"field":"s