 cantidad de platos, velocidades, capacidad y geometría en su configuración documentada."},"evidence_requirements":{"front_chainring_count":"name_reading_hint_only","drivetrain_speeds":"name_reading_hint_only","front_derailleur_mount_type":"oem_or_package","front_derailleur_clamp_mm":"oem_or_package","front_derailleur_cable_pull":"oem_spec","front_derailleur_swing":"oem_spec","front_derailleur_pull_direction":"name_reading_hint_only","shift_actuation_family":"oem_spec","drivetrain_primary_ecosystem":"name_reading_hint_only","drivetrain_declared_compatible_ecosystems":"oem_spec","drivetrain_platform":"oem_spec","spec_evidence_source":"oem_or_package","front_derailleur_clamp_options":"oem_or_package","front_derailleur_cable_anchor":"oem_or_package","front_derailleur_compatibility_claims":"oem_or_package","front_derailleur_application_configurations":"oem_or_package"},"row_conditions":{"version":1,"fields":{"front_derailleur_compatibility_claims":{"allowed_when":{"brand":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"model":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"declared_interface":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Interfaz o estándar documentado"}]]}},"required_when":{"brand":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"model":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"declared_interface":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Interfaz o estándar documentado"}]]},"conditions":{"kind":"when","rows":[[{"field":"declaration_result","operator":"eq","value_type":"token","value":"Condicional declarado"}]]}}},"front_derailleur_application_configurations":{"allowed_when":{"top_m