e":{"kind":"when","rows":[[{"field":"shifter_position","operator":"in","value_type":"token","value":["Izquierdo / delantero","Derecho / trasero","Universal"]}]]},"shifter_control_style":{"kind":"when","rows":[[{"field":"shifter_position","operator":"in","value_type":"token","value":["Izquierdo / delantero","Derecho / trasero","Universal"]}]]},"shifter_unit_count":{"kind":"when","rows":[[{"field":"shifter_position","operator":"eq","value_type":"token","value":"Par"}]]},"shifter_units":{"kind":"when","rows":[[{"field":"shifter_position","operator":"eq","value_type":"token","value":"Par"}]]},"shifter_compatibility_claims":{"kind":"when","rows":[[{"field":"shifter_position","operator":"in","value_type":"token","value":["Izquierdo / delantero","Derecho / trasero","Universal"]}]]},"shifter_unit_compatibility_claims":{"kind":"when","rows":[[{"field":"shifter_position","operator":"eq","value_type":"token","value":"Par"}]]}},"required_when":{"shifter_position":{"kind":"always"},"shifter_indexed_positions":{"kind":"when","rows":[[{"field":"shifter_position","operator":"in","value_type":"token","value":["Izquierdo / delantero","Derecho / trasero","Universal"]},{"field":"shifter_actuation_mode","operator":"in","value_type":"token","value":["Indexado","Conmutable entre indexado y fricción"]}]]},"handlebar_clamp_mm":{"kind":"never"},"drivetrain_speeds":{"kind":"never"},"front_chainring_count":{"kind":"never"},"shift_actuation_family":{"kind":"never"},"derailleur_models_compatible":{"kind":"never"},"kit_members":{"kind":"never"},"drivetrain_primary_ecosystem":{"kind":"never"},"drivetrain_declared_compatible_ecosystems":{"kind":"never"},"drivetrain_platform":{"kind":"never"},"spec_evidence_source":{"kind":"never"},"shifter_actuation_mode":{"kind":"never"},"shifter_control_style":{"kind":"never"},"shifter_unit_count":{"kind":"when","rows":[[{"field":"shifter_position","operator":"eq","value_type":"token","value":"Par"}]]},"shifter_units":{"kind":"when","rows":[[{"field":"shifter_position","operator":"eq","value_type":"token","value":"Par"}]]},"shifter_compatibility_claims":{"kind":"never"},"shifter_unit_compatibility_claims":{"kind":"never"}},"allowed_options":{},"prerequisites":{"shifter_compatibility_claims":["spec_evidence_source"],"shifter_actuation_mode":["spec_evidence_source"],"shifter_control_style":["spec_evidence_source"],"shifter_indexed_positions":["spec_evidence_source"],"handlebar_clamp_mm":["spec_evidence_source"],"shifter_units":["spec_evidence_source"],"shifter_unit_compatibility_claims":["spec_evidence_source"]},"helpers":{"shifter_position":"Qué trae este envase: un mando de un lado, un mando universal, o el par completo. Con «Par» las medidas de cada mando se declaran en su tabla, porque los dos mandos del mismo envase no comparten velocidades ni mecanismo.","shifter_actuation_mode":"Los topes que producen el indexado están en el mando, no en el cambio. Un mando de fricción no tiene posiciones indexadas y un mando conmutable las tiene sólo en su posición indexada.","shifter_control_style":"Cómo se opera la palanca. Es una forma de mando, no una compatibilidad: dos gatillos distintos no son intercambiables por ser gatillos. Un mando integrado con la maneta de freno pertenece a la familia de mando combinado, y esa reasignación se hace con evidencia del producto, no por el título.","shifter_indexed_positions":"Posiciones indexadas de este mando. No es el número de velocidades del grupo ni de la piñonería que hay montada.","handlebar_clamp_mm":"Diámetro del manillar que abraza este mando. En un par, cada mando declara el suyo en la tabla de unidades.","shifter_unit_count":"Un par contiene exactamente dos mandos; cada uno conserva su identidad y su lado.","shifter_units":"Un mando por fila, con su lado, su mecanismo y su documento. Los dos mandos de un par pueden tener distinto número de velocidades y distinto accionamiento; no se promedian ni se copian.","shifter_compatibility_claims":"Declaraciones documentadas de la fuente. Cuando el documento no enumera modelos se declara la interfaz o el estándar; no se inventa un nombre para llenar la celda, y un año ausente en la fuente se deja ausente. Una declaración no convierte a esta pieza en compatible con todo lo que comparta marca o número de velocidades.","shifter_unit_compatibility_claims":"Cada declaración pertenece al mando indicado. No se transmite al otro mando del par."},"evidence_requirements":{"shifter_position":"package_or_label","shifter_indexed_positions":"oem_or_package","handlebar_clamp_mm":"oem_or_package","drivetrain_speeds":"name_reading_hint_only","front_chainring_count":"name_reading_hint_only","shift_actuation_family":"oem_spec","derailleur_models_compatible":"oem_spec","kit_members":"package_or_label","drivetrain_primary_ecosystem":"name_reading_hint_only","drivetrain_declared_compatible_ecosystems":"oem_spec","drivetrain_platform":"oem_spec","spec_evidence_source":"oem_or_package","shifter_actuation_mode":"oem_or_package","shifter_control_style":"oem_or_package","shifter_unit_count":"oem_or_package","shifter_units":"oem_or_package","shifter_compatibility_claims":"oem_or_package","shifter_unit_compatibility_claims":"oem_or_package"},"row_conditions":{"version":1,"fields":{"shifter_units":{"allowed_when":{"indexed_positions":{"kind":"when","rows":[[{"field":"actuation_mode","operator":"in","value_type":"token","value":["Indexado","Conmutable entre indexado y fricción"]}]]}},"required_when":{"indexed_positions":{"kind":"when","rows":[[{"field":"actuation_mode","operator":"in","value_type":"token","value":["Indexado","Conmutable entre indexado y fricción"]}]]}}},"shifter_compatibility_claims":{"allowed_when":{"brand":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"model":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"declared_interface":{"kind":"when","rows":[[{"field":"scope_kind","oper