:{"kind":"always"},"rear_derailleur_application_configurations":{"kind":"always"}},"required_when":{"drivetrain_speeds":{"kind":"never"},"rear_derailleur_max_teeth":{"kind":"never"},"rear_derailleur_min_teeth":{"kind":"never"},"rear_derailleur_total_capacity_teeth":{"kind":"never"},"derailleur_cage_length":{"kind":"never"},"rear_derailleur_mount_type":{"kind":"always"},"derailleur_clutch":{"kind":"never"},"shift_actuation_family":{"kind":"never"},"drivetrain_primary_ecosystem":{"kind":"never"},"drivetrain_declared_compatible_ecosystems":{"kind":"never"},"drivetrain_platform":{"kind":"never"},"spec_evidence_source":{"kind":"never"},"rear_derailleur_spring_return":{"kind":"never"},"rear_derailleur_actuation_ratio_declaration":{"kind":"never"},"rear_derailleur_supplied_mount_adapter":{"kind":"never"},"rear_derailleur_supplied_adapter_reference":{"kind":"never"},"rear_derailleur_compatibility_claims":{"kind":"never"},"rear_derailleur_application_configurations":{"kind":"always"}},"allowed_options":{},"prerequisites":{"rear_derailleur_compatibility_claims":["spec_evidence_source"],"rear_derailleur_spring_return":["spec_evidence_source"],"rear_derailleur_actuation_ratio_declaration":["spec_evidence_source"],"rear_derailleur_supplied_mount_adapter":["spec_evidence_source"],"rear_derailleur_supplied_adapter_reference":["spec_evidence_source"],"rear_derailleur_application_configurations":["spec_evidence_source"]},"helpers":{"rear_derailleur_spring_return":"Hacia dónde vuelve el cambio cuando se suelta el cable. El retorno inverso cambia el sentido de actuación; no prueba por sí solo incompatibilidad con un mando.","rear_derailleur_actuation_ratio_declaration":"La relación entre cable recogido y desplazamiento que declara el documento del fabricante, transcrita tal cual. El nombre comercial de un sistema no es una relación, y esta ficha no la deduce del número de velocidades.","rear_derailleur_supplied_mount_adapter":"Una uña se sostiene con la tuerca del eje o el cierre rápido: es una pieza que viene en el envase. Que venga no cambia la interfaz que el cuadro ofrece.","rear_derailleur_supplied_adapter_reference":"Cómo identifica el documento a esa pieza incluida. Sin pieza incluida no hay referencia que declarar.","rear_derailleur_mount_type":"Cómo se monta este cambio en el cuadro. «Con uña / claw» describe un cambio que se sujeta al eje porque el cuadro no ofrece patilla; que el envase incluya una uña se declara aparte, en el contenido.","derailleur_clutch":"Si el documento declara embrague de cadena. Un nombre de familia o de diseño del cuerpo no prueba que lo tenga.","rear_derailleur_total_capacity_teeth":"Capacidad total que publica el fabricante para este cambio. No se calcula sumando rangos de otras piezas.","derailleur_cage_length":"Largo de jaula que publica el fabricante. La jaula acota la capacidad del modelo; no declara compatibilidad con un mando ni con un grupo.","rear_derailleur_compatibility_claims":"Declaraciones documentadas de la fuente. Cuando el documento no enumera modelos se declara la interfaz o el estándar; no se inventa un nombre para llenar la celda, y un año ausente en la fuente se deja ausente. Una declaración no convierte a esta pieza en compatible con todo lo que comparta marca o número de velocidades.","rear_derailleur_application_configurations":"Una configuración por fila. Velocidades y límites permanecen juntos; no se unen los límites de configuraciones distintas ni se calcula compatibilidad por marca."},"evidence_requirements":{"drivetrain_speeds":"name_reading_hint_only","rear_derailleur_max_teeth":"oem_spec","rear_derailleur_min_teeth":"oem_spec","rear_derailleur_total_capacity_teeth":"oem_spec","derailleur_cage_length":"oem_or_package","rear_derailleur_mount_type":"oem_or_package","derailleur_clutch":"oem_or_package","shift_actuation_family":"oem_spec","drivetrain_primary_ecosystem":"name_reading_hint_only","drivetrain_declared_compatible_ecosystems":"oem_spec","drivetrain_platform":"oem_spec","spec_evidence_source":"oem_or_package","rear_derailleur_spring_return":"oem_or_package","rear_derailleur_actuation_ratio_declaration":"oem_or_package","rear_derailleur_supplied_mount_adapter":"oem_or_package","rear_derailleur_supplied_adapter_reference":"oem_or_package","rear_derailleur_compatibility_claims":"oem_or_package","rear_derailleur_application_configurations":"oem_or_package"},"row_conditions":{"version":1,"fields":{"rear_derailleur_compatibility_claims":{"allowed_when":{"brand":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"model":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"declared_interface":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Interfaz o estándar documentado"}]]}},"required_when":{"brand":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"model":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"declared_interface":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Interfaz o estándar documentado"}]]},"conditions":{"kind":"when","rows":[[{"field":"declaration_result","operator":"eq","value_type":"token","value":"Condicional declarado"}]]}}}}}},"id":"0750e4ac-4615-4ad4-862e-95ac102b12f7","is_active":true,"key":"rear_derailleur","name":"Cambio Trasero","technical_family":"rear_derailleur","tenant_id":null}},{"table":"spec_templates","before":{"contract_version":2,"created_at":"2026-04-26T17:27:33.100573+00:00","default_tags":["drivetrain","derailleur"],"description":"Desviador delantero; compatibilidad por cantidad de platos, tiro y montaje.","form_contract":{"coverage":"template","helpers":{},"labels":{},"prerequisites":{},"roles":{"drivetrain_declared_compatible_ecosystems":"declaration","d