ions":"contents","front_derailleur_cable_anchor":"declaration","front_derailleur_compatibility_claims":"compatibility","front_derailleur_application_configurations":"compatibility"},"labels":{},"allowed_when":{"front_chainring_count":{"kind":"never"},"drivetrain_speeds":{"kind":"never"},"front_derailleur_mount_type":{"kind":"always"},"front_derailleur_clamp_mm":{"kind":"never"},"front_derailleur_cable_pull":{"kind":"always"},"front_derailleur_swing":{"kind":"always"},"front_derailleur_pull_direction":{"kind":"never"},"shift_actuation_family":{"kind":"never"},"drivetrain_primary_ecosystem":{"kind":"never"},"drivetrain_declared_compatible_ecosystems":{"kind":"never"},"drivetrain_platform":{"kind":"never"},"spec_evidence_source":{"kind":"always"},"front_derailleur_clamp_options":{"kind":"when","rows":[[{"field":"front_derailleur_mount_type","operator":"in","value_type":"token","value":["Abrazadera","Otro"]}]]},"front_derailleur_cable_anchor":{"kind":"always"},"front_derailleur_compatibility_claims":{"kind":"always"},"front_derailleur_application_configurations":{"kind":"always"}},"required_when":{"front_chainring_count":{"kind":"never"},"drivetrain_speeds":{"kind":"never"},"front_derailleur_mount_type":{"kind":"always"},"front_derailleur_clamp_mm":{"kind":"never"},"front_derailleur_cable_pull":{"kind":"never"},"front_derailleur_swing":{"kind":"never"},"front_derailleur_pull_direction":{"kind":"never"},"shift_actuation_family":{"kind":"never"},"drivetrain_primary_ecosystem":{"kind":"never"},"drivetrain_declared_compatible_ecosystems":{"kind":"never"},"drivetrain_platform":{"kind":"never"},"spec_evidence_source":{"kind":"never"},"front_derailleur_clamp_options":{"kind":"when","rows":[[{"field":"front_derailleur_mount_type","operator":"eq","value_type":"token","value":"Abrazadera"}]]},"front_derailleur_cable_anchor":{"kind":"never"},"front_derailleur_compatibility_claims":{"kind":"never"},"front_derailleur_application_configurations":{"kind":"always"}},"allowed_options":{},"prerequisites":{"front_derailleur_compatibility_claims":["spec_evidence_source"],"front_derailleur_clamp_options":["spec_evidence_source"],"front_derailleur_cable_anchor":["spec_evidence_source"],"front_derailleur_cable_pull":["spec_evidence_source"],"front_derailleur_swing":["spec_evidence_source"],"front_derailleur_application_configurations":["spec_evidence_source"]},"helpers":{"front_derailleur_clamp_options":"Distingue contacto directo y reducción. El casquillo recibe un tubo menor que la abrazadera. Sus medidas son designaciones nominales de montaje, no cotas mecanizadas. Que un manual admita el casquillo no prueba que venga incluido.","front_derailleur_cable_anchor":"De qué lado del perno pasa el cable según el documento. Cambia cuánto se mueve la jaula por cada milímetro de cable, y por eso no es lo mismo que la dirección desde la que llega el cable.","front_derailleur_cable_pull":"Desde dónde llega el cable al desviador. No describe la geometría de la jaula ni dónde está el pivote.","front_derailleur_swing":"Dónde está el pivote de la jaula. Es una geometría del cuerpo, no la ruta del cable: un título que dice «top pull» no dice si es top swing.","front_derailleur_mount_type":"Cómo se sujeta al cuadro. Park distingue el soporte braze-on del cuadro de una abrazadera propia del desviador.","front_derailleur_compatibility_claims":"Declaraciones documentadas de la fuente. Cuando el documento no enumera modelos se declara la interfaz o el estándar; no se inventa un nombre para llenar la celda, y un año ausente en la fuente se deja ausente. Una declaración no convierte a esta pieza en compatible con todo lo que comparta marca o número de velocidades.","front_derailleur_application_configurations":"El mínimo y máximo de plato grande son dos límites del plato exterior. No son los dientes del plato pequeño y grande montados. Mantén cantidad de platos, velocidades, capacidad y geometría en su configuración documentada."},"evidence_requirements":{"front_chainring_count":"name_reading_hint_only","drivetrain_speeds":"name_reading_hint_only","front_derailleur_mount_type":"oem_or_package","front_derailleur_clamp_mm":"oem_or_package","front_derailleur_cable_pull":"oem_spec","front_derailleur_swing":"oem_spec","front_derailleur_pull_direction":"name_reading_hint_only","shift_actuation_family":"oem_spec","drivetrain_primary_ecosystem":"name_reading_hint_only","drivetrain_declared_compatible_ecosystems":"oem_spec","drivetrain_platform":"oem_spec","spec_evidence_source":"oem_or_package","front_derailleur_clamp_options":"oem_or_package","front_derailleur_cable_anchor":"oem_or_package","front_derailleur_compatibility_claims":"oem_or_package","front_derailleur_application_configurations":"oem_or_package"},"row_conditions":{"version":1,"fields":{"front_derailleur_compatibility_claims":{"allowed_when":{"brand":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"model":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"declared_interface":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Interfaz o estándar documentado"}]]}},"required_when":{"brand":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"model":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"declared_interface":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Interfaz o estándar documentado"}]]},"conditions":{"kind":"when","rows":[[{"field":"declaration_result","operator":"eq","value_type":"token","value":"Condicional declarado"}]]}}},"front_derailleur_application_configurations":{"allowed_when":{"top_middle_difference_teeth":{"kind":"when","rows":[[{"field":"front_chainring_count","operator":"eq","value_type":"decimal","value":"3"}]]}},"required_when":{"chainline_datum":{"kind":"when","rows":[[{"field":"chainline_mm","operator":"gt","value_type":"decimal","value":"0"}]]}}},"front_derailleur_clamp_options":{"allowed_when":{"direct_tube_diameter_mm":{"kind":"when","rows":[[{"field":"attachment_method","operator":"eq","value_type":"token","value":"Abrazadera directa"}]]},"reduced_tube_diameter_mm":{"kind":"when","rows":[[{"field":"attachment_method","operator":"eq","value_type":"token","value":"Abrazadera con casquillo reductor"}]]},"unreduced_clamp_diameter_mm":{"kind":"when","rows":[[{"field":"attachment_method","operator":"eq","value_type":"token","value":"Abrazadera con casquillo reductor"}]]},"adapter_reference":{"kind":"when","rows":[[{"field":"attachment_method","operator":"eq","value_type":"token","value":"Abrazadera con casquillo reductor"}]]},"adapter_included":{"kind":"when","rows":[[{"field":"attachment_method","operator":"eq","value_type":"token","value":"Abrazadera con casquillo reductor"}]]}},"required_when":{"direct_tube_diameter_mm":{"kind":"when","rows":[[{"field":"attachment_method","operator":"eq","value_type":"token","value":"Abrazadera directa"}]]},"reduced_tube_diameter_mm":{"kind":"when","rows":[[{"field":"attachment_method","operator":"eq","value_type":"token","value":"Abrazadera con casquillo reductor"}]]},"unreduced_clamp_diameter_mm":{"kind":"when","rows":[[{"field":"attachment_method","operator":"eq","value_type":"token","value":"Abrazadera con casquillo reductor"}]]},"adapter_reference":{"kind":"when","rows":[[{"field":"attachment_method","operator":"eq","value_type":"token","value":"Abrazadera con casquillo reductor"}]]}}}}}},"id":"590232e5-d21a-4a47-9419-1bf42e6b1922","is_active":true,"key":"front_derailleur","name":"Desviador Delantero","technical_family":"front_derailleur","tenant_id":null}}],"adjudication":{"status":"candidate_under_sole_owner_review","scope":"Shifter, rear and front derailleur owners; combined controls, identity and fill stay outside.","preimage":"Fresh 2026-09-16 production capture equals the 2026-09-08 final preimage in templates, fields and shared definitions; effective bindings 32+35+15 -> 36+40+18.","dead_on_arrival_dropped":{"front_derailleur":["max_chainring_teeth"]},"dead_on_arrival_reason":"max_chainring_teeth was a new definition placed in the legacy section after the maximum moved into documented configurations; no case, helper or observation depends on it, so it is not created.","actuation":"Index or friction is a property of the control, filled from package or manual, never from a title.","speeds":"Each documented configuration carries its own speed count; one row cannot hold two counts.","combined_controls":"Combined shift/brake units belong to brake_shift_combined_control through the assignment queue.","legacy":"Published platform, ecosystem, speed and teeth readings are retained without becoming active compatibility.","reviews":"Claude review H1-H5 adjudicated by Root (2026-09-08); no open blocker on the metadata.","released_client":"f51f3777 decodes row_conditions and row_coherence; no scalar pairs and no strict order here.","compatibility_and_fill_not_approved":true,"new_scalar_surfaces":["front_derailleur_cable_anchor","front_derailleur_cable_pull","front_derailleur_swing","rear_derailleur_spring_return","rear_derailleur_supplied_mount_adapter","shifter_actuation_mode","shifter_control_style","shifter_unit_count"]},"product_writes":false,"fill_allowed":false,"mechanical_approval":false}$nd_catalog$::jsonb);
create temporary table nd_publication_before on commit drop as select
 (select md5(coalesce(jsonb_agg(to_jsonb(f) order by f.id),'[]')::text) from public.spec_facts f) facts,
 (select md5(coalesce(jsonb_agg(jsonb_build_array(p.id,p.spec_revision,p.spec_template_id,p.spec_reference_id) order by p.id),'[]')::text) from public.products p) products,
 (select md5(coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]')::text) from public.product_spec_references r) references,
 (select md5(coalesce(jsonb_agg(to_jsonb(m) order by m.id),'[]')::text) from public.category_tech_mappings m) category_defaults;

do $publish$
declare doc jsonb; v_wanted jsonb; v_actual jsonb; patch jsonb;
begin
 select d.doc into doc from nd_publication_document d;
 if md5(pg_get_functiondef(to_regprocedure(
   'public.spec_validate_draft_internal_v1(uuid,jsonb,text,text,text,text)')))
   is distinct from 'ac0738d5c2039412b603dc71adc41721' then
   raise exception 'Unreviewed specification validator';
 end if;
 if exists(select 1 from jsonb_array_elements(doc->'records'->'spec_templates') w
    join public.spec_templates t on t.key=w->>'key'
    and (t.tenant_id is null or t.tenant_id=(doc->>'audited_tenant_id')::uuid)
    where t.id<>(w->>'id')::uuid)
 or exists(select 1 from jsonb_array_elements(doc->'records'->'spec_definitions') w
    join public.spec_definitions d on d.key=w->>'key'
    and (d.tenant_id is null or d.tenant_id=(doc->>'audited_tenant_id')::uuid)
    where d.id<>(w->>'id')::uuid) then
   raise exception 'Publication key collision';
 end if;
 if exists(select 1 from jsonb_array_elements(doc->'reused_definitions') wanted
   left join public.spec_definitions actual on actual.id=(wanted->>'id')::uuid
   where actual.id is null or to_jsonb(actual) is distinct from wanted-'options'
   or (select coalesce(jsonb_agg(to_jsonb(v) order by v.id),'[]')
       from public.spec_definition_values v where v.spec_definition_id=actual.id)
      is distinct from wanted->'options') then
   raise exception 'Forward publication shared-definition drift';
 end if;
 if ((not exists (
 select 1 from jsonb_array_elements(doc->'records'->'spec_definitions') wanted
 left join public.spec_definitions actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or (select jsonb_object_agg(k,to_jsonb(actual)->k)
 from jsonb_object_keys(wanted) k) is distinct from wanted)) and
(not exists (
 select 1 from jsonb_array_elements(doc->'records'->'spec_definition_values') wanted
 left join public.spec_definition_values actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or (select jsonb_object_agg(k,to_jsonb(actual)->k)
 from jsonb_object_keys(wanted) k) is distinct from wanted)) and
(not exists (
 select 1 from jsonb_array_elements(doc->'records'->'spec_templates') wanted
 left join public.spec_templates actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or (select jsonb_object_agg(k,to_jsonb(actual)->k)
 from jsonb_object_keys(wanted) k) is distinct from wanted)) and
(not exists (
 select 1 from jsonb_array_elements(doc->'records'->'spec_template_fields') wanted
 left join public.spec_template_fields actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or (select jsonb_object_agg(k,to_jsonb(actual)->k)
 from jsonb_object_keys(wanted) k) is distinct from wanted)) and
(not exists (select 1 from public.spec_template_fields f
 where f.template_id in (select (t->>'id')::uuid from jsonb_array_elements(doc->'records'->'spec_templates') t)
 and f.id not in (select (f->>'id')::uuid from jsonb_array_elements(doc->'records'->'spec_template_fields') f))) and
(not exists (select 1 from public.spec_definition_values v
 where v.spec_definition_id in (select (d->>'id')::uuid from jsonb_array_elements(doc->'records'->'spec_definitions') d)
 and v.id not in (select (v->>'id')::uuid from jsonb_array_elements(doc->'records'->'spec_definition_values') v))) and
(not exists (select 1 from jsonb_array_elements(doc->'reused_definitions') wanted
 left join public.spec_definitions d on d.id=(wanted->>'id')::uuid
 where d.id is null or to_jsonb(d) is distinct from wanted-'options'
 or (select coalesce(jsonb_agg(to_jsonb(v) order by v.id),'[]')
     from public.spec_definition_values v where v.spec_definition_id=d.id) is distinct from wanted->'options'))) then
   return; -- Exact replay must not increment any revision.
 end if;
 if not ((not exists (
 select 1 from jsonb_array_elements(doc->'before'->'spec_templates') wanted
 left join public.spec_templates actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or to_jsonb(actual) is distinct from wanted)) and
(not exists (
 select 1 from jsonb_array_elements(doc->'before'->'spec_template_fields') wanted
 left join public.spec_template_fields actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or to_jsonb(actual) is distinct from wanted)) and
(not exists (select 1 from public.spec_template_fields actual
 where actual.template_id in (select (t->>'id')::uuid
 from jsonb_array_elements(doc->'before'->'spec_templates') t)
 and actual.id not in (select (f->>'id')::uuid
 from jsonb_array_elements(doc->'before'->'spec_template_fields') f))) and
(not exists (select 1
 from jsonb_array_elements(doc->'records'->'spec_template_fields') wanted
 join public.spec_template_fields actual on actual.id=(wanted->>'id')::uuid
 where wanted->>'id' not in (select f->>'id'
 from jsonb_array_elements(doc->'before'->'spec_template_fields') f)))) then
   raise exception 'Forward publication preimage drift';
 end if;
 
 for v_wanted in select value from jsonb_array_elements(doc->'records'->'spec_definitions') loop
   select to_jsonb(t) into v_actual from public.spec_definitions t where id=(v_wanted->>'id')::uuid;
   if found then
     raise exception 'Forward publication new-record collision in spec_definitions: %',v_wanted->>'id';
   end if;
   insert into public.spec_definitions(id,tenant_id,key,label,data_type,unit,allowed_values,validation_rules,is_customer_visible,is_compatibility_relevant,description,is_filterable,is_required_by_default,is_mechanic_visible,group_name,sort_order)
   select id,tenant_id,key,label,data_type,unit,allowed_values,validation_rules,is_customer_visible,is_compatibility_relevant,description,is_filterable,is_required_by_default,is_mechanic_visible,group_name,sort_order from jsonb_populate_record(null::public.spec_definitions,v_wanted);
 end loop;
 for v_wanted in select value from jsonb_array_elements(doc->'records'->'spec_definition_values') loop
   select to_jsonb(t) into v_actual from public.spec_definition_values t where id=(v_wanted->>'id')::uuid;
   if found then
     raise exception 'Forward publication new-record collision in spec_definition_values: %',v_wanted->>'id';
   end if;
   insert into public.spec_definition_values(id,tenant_id,spec_definition_id,code,label,sort_order,is_active)
   select id,tenant_id,spec_definition_id,code,label,sort_order,is_active from jsonb_populate_record(null::public.spec_definition_values,v_wanted);
 end loop;
 -- Template first, then changed/new fields. Each real edit bumps the native
 -- revision once; unchanged fields never receive an UPDATE.
 for patch in select value from jsonb_array_elements(doc->'patches')
     where value->>'table'='spec_templates' loop
   update public.spec_templates set form_contract=patch->'after'->'form_contract'
   where id=(patch->'before'->>'id')::uuid;
 end loop;
 for patch in select value from jsonb_array_elements(doc->'patches')
     where value->>'table'='spec_template_fields' loop
   update public.spec_template_fields set (section_key,sort_order,is_required,visibility_rules,option_rules,constraint_rules,default_value_json,helper_text)=(
     select section_key,sort_order,is_required,visibility_rules,option_rules,constraint_rules,default_value_json,helper_text from jsonb_populate_record(
       null::public.spec_template_fields,patch->'after'))
   where id=(patch->'before'->>'id')::uuid;
 end loop;
 for v_wanted in select value from jsonb_array_elements(doc->'records'->'spec_template_fields')
     where value->>'id' not in (select f->>'id'
       from jsonb_array_elements(doc->'before'->'spec_template_fields') f) loop
   insert into public.spec_template_fields(id,tenant_id,template_id,spec_definition_id,section_key,sort_order,is_required,visibility_rules,option_rules,constraint_rules,default_value_json,helper_text)
   select id,tenant_id,template_id,spec_definition_id,section_key,sort_order,is_required,visibility_rules,option_rules,constraint_rules,default_value_json,helper_text from jsonb_populate_record(null::public.spec_template_fields,v_wanted);
 end loop;
end $publish$;

set constraints all immediate;
select 1/(case when (not exists (
 select 1 from jsonb_array_elements(doc->'records'->'spec_definitions') wanted
 left join public.spec_definitions actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or (select jsonb_object_agg(k,to_jsonb(actual)->k)
 from jsonb_object_keys(wanted) k) is distinct from wanted)) and
(not exists (
 select 1 from jsonb_array_elements(doc->'records'->'spec_definition_values') wanted
 left join public.spec_definition_values actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or (select jsonb_object_agg(k,to_jsonb(actual)->k)
 from jsonb_object_keys(wanted) k) is distinct from wanted)) and
(not exists (
 select 1 from jsonb_array_elements(doc->'records'->'spec_templates') wanted
 left join public.spec_templates actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or (select jsonb_object_agg(k,to_jsonb(actual)->k)
 from jsonb_object_keys(wanted) k) is distinct from wanted)) and
(not exists (
 select 1 from jsonb_array_elements(doc->'records'->'spec_template_fields') wanted
 left join public.spec_template_fields actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or (select jsonb_object_agg(k,to_jsonb(actual)->k)
 from jsonb_object_keys(wanted) k) is distinct from wanted)) and
(not exists (select 1 from public.spec_template_fields f
 where f.template_id in (select (t->>'id')::uuid from jsonb_array_elements(doc->'records'->'spec_templates') t)
 and f.id not in (select (f->>'id')::uuid from jsonb_array_elements(doc->'records'->'spec_template_fields') f))) and
(not exists (select 1 from public.spec_definition_values v
 where v.spec_definition_id in (select (d->>'id')::uuid from jsonb_array_elements(doc->'records'->'spec_definitions') d)
 and v.id not in (select (v->>'id')::uuid from jsonb_array_elements(doc->'records'->'spec_definition_values') v))) and
(not exists (select 1 from jsonb_array_elements(doc->'reused_definitions') wanted
 left join public.spec_definitions d on d.id=(wanted->>'id')::uuid
 where d.id is null or to_jsonb(d) is distinct from wanted-'options'
 or (select coalesce(jsonb_agg(to_jsonb(v) order by v.id),'[]')
     from public.spec_definition_values v where v.spec_definition_id=d.id) is distinct from wanted->'options')) then 1 else 0 end) as exact_metadata
from nd_publication_document;
select 1/(case when b.facts=(select md5(coalesce(jsonb_agg(to_jsonb(f) order by f.id),'[]')::text) from public.spec_facts f)
 and b.products=(select md5(coalesce(jsonb_agg(jsonb_build_array(p.id,p.spec_revision,p.spec_template_id,p.spec_reference_id) order by p.id),'[]')::text) from public.products p)
 and b.references=(select md5(coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]')::text) from public.product_spec_references r)
 and b.category_defaults=(select md5(coalesce(jsonb_agg(to_jsonb(m) order by m.id),'[]')::text) from public.category_tech_mappings m)
 then 1 else 0 end) as product_observations_and_identity_unchanged from nd_publication_before b;
commit;
